def Wall_back_ram():
  global HowFar_, HowFarUntilFrontRow, rychlost, gyro, HowFarUntilBackRow, pas, left, Start_stop, right, TouchZavora, US
  rychlost = 360
  while not sensor_retry(Start_stop, Start_stop.is_pressed):
    motor_retry(left, lambda: left.run_at_speed(-rychlost - 8 * sensor_retry(gyro, gyro.angle)))
    motor_retry(right, lambda: right.run_at_speed(-rychlost + 8 * sensor_retry(gyro, gyro.angle)))
    if rychlost > 40:
      rychlost = rychlost - 0.1
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)
  motor_retry(left, lambda: left.run_at_speed(-180))
  motor_retry(right, lambda: right.run_at_speed(-180))
  time.sleep(1)
  motor_retry(left, left.brake)
  motor_retry(right, right.brake)
  sensor_retry(gyro, gyro.set_zero_point)
  time.sleep(0.5)


